const section = (heading, text) => ({ heading, text });
const graph = (title, desc, caption, nodes, edges) => ({
    type: "graph", title, desc, caption, height: 250,
    nodes: nodes.map(([id, label, sub, x, y, tone = 1]) => ({ id, label, sub, x, y, tone })),
    edges: edges.map(([from, to, label]) => ({ from, to, label, arrow: "both" }))
});
const lesson = (id, number, title, intro, sections, example, misconception, reflection) => ({
    id: `advanced-${id}-${number}`, title, intro,
    sections: sections.map(([heading, text]) => section(heading, text)),
    example: { title: example[0], text: example[1] }, misconception,
    reflection: { prompt: reflection[0], answer: reflection[1] }
});
const module = (id, title, summary, goals, review, studio, figure, lessons) => ({
    id, title, summary, goals,
    lessons: lessons.map((item, index) => ({
        ...item, review: review.map(([href, label]) => ({ href, label })),
        studio: index === 0 && studio ? [{ id: studio[0], label: studio[1], instruction: studio[2] }] : [],
        figures: index === 0 && figure ? [figure] : []
    }))
});

